/* fae-safety-sim 엔진 — FOR ALL ENTRIES의 빈 기준 테이블 함정을 시뮬레이션.
   기준 목록(driver 내부 테이블) × 안전장치(IS NOT INITIAL) 조합으로 실행 → 제한 조회 / 빈 목록 보호 / 전체 조회 위험.
   골격 계약: .fae-keys(기준목록 버튼) · [data-safety] · #faeList · [data-run] · #faeCode · #faeStatus · #faeBody.
   config: window.FAE_CFG = { rows:[..], cols:[{key,label}], keySets:[{label,ids:[..]}],
            keyField, driver, into, table, selFields, quote, keyNoun, rowNoun, unit }.
   높이: _autoheight.js. */
(function () {
  var CFG = window.FAE_CFG || { rows: [], keySets: [], cols: [] };
  var ROWS = CFG.rows || [];
  var KEY = CFG.keyField;                    // 기준 목록과 맞출 필드명
  var DRV = CFG.driver || 'lt_key';          // 기준 내부 테이블 이름
  var INTO = CFG.into || 'lt_data';          // 결과 내부 테이블 이름
  var TBL = CFG.table || 'ztable';           // 조회 대상 DB 테이블
  var SEL = CFG.selFields || '*';            // SELECT 필드 목록
  var KEYN = CFG.keyNoun || '키';
  var ROWN = CFG.rowNoun || '행';
  var UNIT = CFG.unit || '행';
  var setIdx = 0;          // keySets 인덱스(기준 목록)
  var safety = true;
  var lastRun = null;      // {mode, rows}

  var keysEl = document.querySelector('.fae-keys');
  var safetyBtn = document.querySelector('[data-safety]');
  var listEl = document.getElementById('faeList');
  var runBtn = document.querySelector('[data-run]');
  var codeEl = document.getElementById('faeCode');
  var statusEl = document.getElementById('faeStatus');
  var bodyEl = document.getElementById('faeBody');

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }
  function ids() { return CFG.keySets[setIdx].ids; }
  function distinctIds() { var s = {}, o = []; ids().forEach(function (d) { if (!(d in s)) { s[d] = 1; o.push(d); } }); return o; }
  function disp(v) { return CFG.quote ? "'" + v + "'" : String(v); }

  function renderKeyBtns() {
    keysEl.innerHTML = CFG.keySets.map(function (s, i) {
      return '<button class="fae-btn" type="button" data-i="' + i + '" aria-pressed="' + (i === setIdx ? 'true' : 'false') + '">' + esc(s.label) + '</button>';
    }).join('');
  }
  function renderList() {
    var v = ids();
    listEl.innerHTML = DRV + ' = ' + (v.length
      ? '[ ' + esc(v.map(disp).join(', ')) + ' ]'
      : '<span class="empty">[ ] (빈 테이블)</span>');
  }
  function renderCode() {
    var guardOn = safety;
    var lines = [];
    if (guardOn) lines.push('<span class="gd">IF ' + DRV + ' IS NOT INITIAL.</span>');
    var ind = guardOn ? '  ' : '';
    lines.push(ind + '<span class="kw">SELECT</span> ' + SEL);
    lines.push(ind + '  <span class="kw">FROM</span> ' + TBL);
    lines.push(ind + '  <span class="kw">INTO CORRESPONDING FIELDS OF TABLE</span> ' + INTO);
    lines.push(ind + '  <span class="kw">FOR ALL ENTRIES IN</span> ' + DRV);
    lines.push(ind + '  <span class="kw">WHERE</span> ' + KEY + ' = ' + DRV + '-' + KEY + '.');
    if (guardOn) lines.push('<span class="gd">ENDIF.</span>');
    else lines.push('<span class="dim">" ⚠️ IS NOT INITIAL 보호 없음</span>');
    codeEl.innerHTML = lines.join('\n');
  }

  function run() {
    var empty = ids().length === 0;
    if (empty && safety) {
      lastRun = { mode: 'safe', rows: [] };
      statusEl.className = 'fae-status safe';
      statusEl.innerHTML = '🛡️ <b>' + DRV + '</b>가 비어 <b>IS NOT INITIAL</b>이 막았습니다 → SELECT 실행 안 함. (sy-dbcnt는 갱신되지 않으니 이전 값에 의존 금지)';
      bodyEl.innerHTML = '<tr><td colspan="' + CFG.cols.length + '" class="fae-empty">SELECT 실행 안 함 — ' + INTO + ' 변화 없음.</td></tr>';
      return;
    }
    if (empty && !safety) {
      lastRun = { mode: 'danger', rows: ROWS.slice() };
      statusEl.className = 'fae-status danger';
      statusEl.innerHTML = '⚠️ <b>위험!</b> 빈 ' + DRV + '라 WHERE가 통째로 무시됨 → <b>전체 ' + ROWS.length + UNIT + '</b> 조회(운영이면 사고). 이래서 IS NOT INITIAL은 필수입니다.';
      renderRows(ROWS, true);
      return;
    }
    // 정상: distinct 키로 필터(중복 제거된 결과)
    var di = distinctIds();
    var rows = ROWS.filter(function (r) { return di.indexOf(r[KEY]) >= 0; });
    lastRun = { mode: 'ok', rows: rows };
    statusEl.className = 'fae-status ok';
    var dupNote = ids().length !== di.length
      ? ' (입력에 중복 ' + KEYN + '가 있었지만 결과는 ' + ROWN + ' 기준 — 입력 개수와 결과 행수를 단순 비교 금지)'
      : '';
    statusEl.innerHTML = '✅ 기준 ' + KEYN + ' ' + di.length + '개로 제한 조회 → <b>' + rows.length + UNIT + '</b> · sy-dbcnt = ' + rows.length + dupNote;
    renderRows(rows, false);
  }
  function renderRows(rows, over) {
    if (!rows.length) { bodyEl.innerHTML = '<tr><td colspan="' + CFG.cols.length + '" class="fae-empty">0' + UNIT + '</td></tr>'; return; }
    bodyEl.innerHTML = rows.map(function (r) {
      return '<tr class="' + (over ? 'over' : '') + '">' + CFG.cols.map(function (c) { return '<td>' + esc(r[c.key]) + '</td>'; }).join('') + '</tr>';
    }).join('');
  }

  function render() {
    renderKeyBtns(); renderList(); renderCode();
    safetyBtn.setAttribute('aria-pressed', safety ? 'true' : 'false');
    safetyBtn.textContent = safety ? 'IS NOT INITIAL: ON 🛡️' : 'IS NOT INITIAL: OFF ⚠️';
  }

  keysEl.addEventListener('click', function (e) { var b = e.target.closest('.fae-btn'); if (!b) return; setIdx = +b.getAttribute('data-i'); render(); });
  safetyBtn.addEventListener('click', function () { safety = !safety; render(); });
  runBtn.addEventListener('click', run);

  render();
  // 초기 안내
  statusEl.className = 'fae-status';
  statusEl.innerHTML = '기준 목록과 안전장치를 고르고 <b>▶ 실행</b>을 눌러 결과를 보세요.';
  bodyEl.innerHTML = '<tr><td colspan="' + CFG.cols.length + '" class="fae-empty">▶ 실행 전</td></tr>';
})();

// ===== module-choice-cards 엔진 JS — 상황별 모듈화 도구 선택(N지선다) (CH10-L06) =====
// 상황 카드를 여러 도구 중 하나로 분류하면 정답·이유를 보여 준다. 데이터=window.MCC_CFG.
//   MCC_CFG = { choices:[{key,label}], cards:[{q, ans(key), why}] }
(function(){
  var cfg = window.MCC_CFG || {};
  var CHOICES = cfg.choices || [];
  var CARDS = cfg.cards || [];
  var $=function(id){return document.getElementById(id);};
  function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
  function label(key){ var c=CHOICES.filter(function(x){return x.key===key;})[0]; return c?c.label:key; }

  var answered={};

  function render(){
    $('cards').innerHTML = CARDS.map(function(c,i){
      var chosen=answered[i], done=chosen!=null, correct=done&&chosen===c.ans;
      var btns=CHOICES.map(function(ch){
        var cls='cbtn'; if(chosen===ch.key) cls+=' chosen';
        if(done){ if(ch.key===c.ans) cls+=' right'; else if(chosen===ch.key) cls+=' wrong'; }
        return '<button class="'+cls+'" data-i="'+i+'" data-k="'+ch.key+'" '+(done?'disabled':'')+'>'+esc(ch.label)+'</button>';
      }).join('');
      var fb = done ? '<div class="fb '+(correct?'ok':'no')+'">'+(correct?'✓ 정답':'✕ 정답: '+esc(label(c.ans)))+' — '+esc(c.why)+'</div>' : '';
      return '<div class="card'+(done?' done':'')+'"><div class="card__q">'+esc(c.q)+'</div><div class="choices">'+btns+'</div>'+fb+'</div>';
    }).join('');
    var ans=Object.keys(answered).length;
    var ok=CARDS.filter(function(c,i){return answered[i]===c.ans;}).length;
    $('score').textContent='정답 '+ok+' / '+CARDS.length+(ans<CARDS.length?'  (푼 문제 '+ans+')':'');
    postHeight();
  }

  $('cards').addEventListener('click',function(e){
    var b=e.target.closest('.cbtn'); if(!b||b.disabled) return;
    var i=+b.dataset.i; if(answered[i]!=null) return;
    answered[i]=b.dataset.k; render();
  });
  $('reset').addEventListener('click',function(){ answered={}; render(); });

  function postHeight(){ try{ var el=document.querySelector('.wrap');
    var h=Math.ceil(el?el.getBoundingClientRect().bottom:document.body.scrollHeight)+8;
    parent.postMessage({sda:'embed-height', h:h}, '*'); }catch(e){} }
  window.addEventListener('load', postHeight);
  window.addEventListener('resize', postHeight);

  render();
})();

// ===== join-aggregate-visualizer 엔진 JS — LEFT OUTER JOIN + GROUP BY SUM 시각화 (config 주도) =====
// window.JOIN_CFG:
//   { left:{name,alias,cols[{key,label,num}],data[]}, right:{name,alias,cols[],data[]},
//     onLeft, onRight, filter:{field,op,val,label}, groupBy[leftKeys], sumField, sumAs, resultCols[{key,label,num}] }
// JOIN 타입(LEFT OUTER ↔ INNER) 토글로 '예매 없는 공연이 남는다'(LEFT) 차이를 시연. classic SELECT.
(function(){
  var cfg = window.JOIN_CFG; if(!cfg) return;
  var L=cfg.left, R=cfg.right;
  var $=function(id){return document.getElementById(id);};
  var jtype='LEFT';   // 'LEFT' | 'INNER'

  function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
  function filterPass(rrow){
    if(!cfg.filter) return true;
    var v=rrow[cfg.filter.field], t=cfg.filter.val;
    return cfg.filter.op==='<>' ? String(v)!==String(t) : String(v)===String(t);
  }
  // 각 left행에 매칭되는(필터 통과) right행들
  function matchesFor(lrow){
    return R.data.filter(function(rr){ return String(rr[cfg.onRight])===String(lrow[cfg.onLeft]) && filterPass(rr); });
  }

  /* ── 원본 테이블 ── */
  function tableHtml(meta){
    var th='<thead><tr>'+meta.cols.map(function(c){return '<th>'+c.label+'</th>';}).join('')+'</tr></thead>';
    var bd='<tbody>'+meta.data.map(function(r){
      var cancelled = (meta===R && cfg.filter && !filterPass(r));
      return '<tr class="'+(cancelled?'cx':'')+'">'+meta.cols.map(function(c){return '<td class="'+(c.num?'num':'')+'">'+esc(r[c.key])+'</td>';}).join('')+'</tr>';
    }).join('')+'</tbody>';
    return th+bd;
  }
  function renderSrc(){
    $('srcL').innerHTML=tableHtml(L);
    $('srcR').innerHTML=tableHtml(R);
  }

  /* ── 코드 ── */
  function renderCode(){
    var join = jtype==='LEFT' ? 'LEFT OUTER JOIN' : 'INNER JOIN';
    var onTxt = L.alias+'~'+cfg.onLeft+' = '+R.alias+'~'+cfg.onRight + (cfg.filter? ' AND '+cfg.filter.label : '');
    var selFields = cfg.groupBy.map(function(k){return L.alias+'~'+k;}).join(' ')+' SUM( '+R.alias+'~'+cfg.sumField+' ) AS '+cfg.sumAs;
    var grpFields = cfg.groupBy.map(function(k){return L.alias+'~'+k;}).join(' ');
    var lines=[
      'SELECT '+selFields,
      '  FROM '+L.name+' AS '+L.alias,
      '  '+join+' '+R.name+' AS '+R.alias,
      '    ON '+onTxt,
      // 결과 itab은 전역 위치라 g 접두어(R11) · 필드를 나열해 읽으므로 이름끼리 맞추는 CORRESPONDING
      '  INTO CORRESPONDING FIELDS OF TABLE '+(cfg.intoTarget||'gt_stat'),
      '  GROUP BY '+grpFields+'.'
    ];
    var KW=new Set(['SELECT','SUM','AS','FROM','LEFT','OUTER','INNER','JOIN','ON','AND','INTO','CORRESPONDING','FIELDS','OF','TABLE','GROUP','BY']);
    $('javCode').innerHTML = lines.map(function(ln){
      return ln.replace(/[A-Za-z_][A-Za-z0-9_~]*/g,function(w){
        var bare=w.replace(/~.*/,''); // alias~field → 키워드 아님
        return (KW.has(w.toUpperCase()) && w.indexOf('~')<0) ? '<span class="tok-kw">'+w+'</span>' : w;
      }).replace(/'[^']*'/g,function(m){return '<span class="tok-str">'+m+'</span>';});
    }).join('\n');
  }

  /* ── 집계 결과 ── */
  function renderResult(){
    var html='';
    L.data.forEach(function(lrow){
      var ms=matchesFor(lrow);
      if(jtype==='INNER' && ms.length===0) return;   // INNER: 매칭 없으면 제외
      var booked=ms.reduce(function(s,r){return s+(Number(r[cfg.sumField])||0);},0);
      var emptyLeft = ms.length===0;  // LEFT에서만 도달
      var keyTxt = cfg.groupBy.map(function(k){
        var meta=L.cols.filter(function(c){return c.key===k;})[0];
        return (meta?meta.label:k)+' <b>'+esc(lrow[k])+'</b>';
      }).join(' · ');
      var chips = emptyLeft
        ? '<span class="bk-none">예매 없음 — LEFT라서 0으로 남음</span>'
        : ms.map(function(r){ return '<span class="bk-chip">'+esc(r.customer||r[cfg.onRight])+' '+esc(r[cfg.sumField])+'</span>'; }).join('');
      html += '<div class="jav-rrow'+(emptyLeft?' empty-left':'')+'">'+
        '<span class="jav-key">'+keyTxt+'</span>'+
        '<span class="jav-chips">'+chips+'</span>'+
        '<span class="jav-sum">'+cfg.sumAs+' = '+booked+'</span>'+
      '</div>';
    });
    $('javRes').innerHTML=html;
    postHeight();
  }

  function refresh(){ renderCode(); renderResult(); }

  /* ── 토글 ── */
  $('javToggle').addEventListener('click',function(e){
    var b=e.target.closest('button'); if(!b) return;
    jtype=b.dataset.j;
    $('javToggle').querySelectorAll('button').forEach(function(x){x.classList.toggle('on',x===b);});
    $('javHint').innerHTML = jtype==='LEFT'
      ? '🟡 <b>LEFT OUTER JOIN</b> — 예매가 하나도 없는 공연도 결과에 <b>남습니다</b>(booked 0). 빈 행 = 강조.'
      : '⚪ <b>INNER JOIN</b> — 매칭되는 예매가 있는 공연만 남습니다. 예매 0인 공연은 <b>사라집니다</b>.';
    refresh();
  });

  /* iframe 자동 높이 */
  function postHeight(){
    try{ var el=document.querySelector('.wrap');
      var h=Math.ceil(el?el.getBoundingClientRect().height:document.body.scrollHeight)+6;
      parent.postMessage({sda:'embed-height', h:h}, '*'); }catch(e){}
  }
  window.addEventListener('load', postHeight);
  window.addEventListener('resize', postHeight);

  renderSrc(); refresh();
})();
